const ADMIN_IDLE_TIMEOUT_MS = 30 * 60 * 1000;
let adminIdleTimer = 0;
function closeAdminSession() {
  window.clearTimeout(adminIdleTimer);
  adminIdleTimer = 0;
  sessionStorage.removeItem("immeubleassur_admin_token");
  window.location.reload();
}
function armAdminIdleTimeout() {
  window.clearTimeout(adminIdleTimer);
  if (!sessionStorage.getItem("immeubleassur_admin_token")) return;
  adminIdleTimer = window.setTimeout(closeAdminSession, ADMIN_IDLE_TIMEOUT_MS);
}
["pointerdown", "keydown", "input"].forEach((eventName) => {
  document.addEventListener(eventName, armAdminIdleTimeout, { passive: true });
});
form?.addEventListener("submit", () => window.setTimeout(armAdminIdleTimeout, 0), { capture: true });
armAdminIdleTimeout();
